import{_ as t,o,a as n,a3 as a}from"./chunks/framework.CnT1yzXN.js";const f=JSON.parse('{"title":"Stuzhik Connect","description":"Stuzhik Connect — direct P2P transfer of modpacks and builds between friends, with no servers. Friends list, connection codes, VPN, security.","frontmatter":{"description":"Stuzhik Connect — direct P2P transfer of modpacks and builds between friends, with no servers. Friends list, connection codes, VPN, security.","head":[["meta",{"name":"keywords","content":"stuzhik connect, send modpack to friend, share minecraft modpack, p2p minecraft, share minecraft builds, minecraft without server"}]]},"headers":[],"relativePath":"en/guide/connect.md","filePath":"en/guide/connect.md"}'),r={name:"en/guide/connect.md"};function i(s,e,d,l,h,u){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="stuzhik-connect" tabindex="-1">Stuzhik Connect <a class="header-anchor" href="#stuzhik-connect" aria-label="Permalink to &quot;Stuzhik Connect&quot;">​</a></h1><p>Direct transfer of builds and modpacks between devices — no intermediate servers, no uploading to the cloud. Files go straight from you to your friend.</p><div class="warning custom-block"><p class="custom-block-title">Important: works within a single network</p><p>Stuzhik finds devices by itself <strong>on the same network</strong> — an ordinary home/local one, or a virtual one set up by a VPN app. Stuzhik has no server of its own for connecting over the internet: if you and your friend are on different networks (different homes, cities, ISPs), your home routers will almost always block a direct connection between you.</p><p>If you&#39;re on the same network (same Wi-Fi/LAN), it just works. If you&#39;re on different ones, you need a shared VPN, see <a href="#if-you-are-on-different-networks">below</a>.</p></div><div class="info custom-block"><p class="custom-block-title">Version 0.0.19 or newer required — for both of you</p><p>Since version 0.0.19, Connect uses a new protocol (Connect 2). Launchers 0.0.18 and older can&#39;t connect to it at all — both of you need to update. If there&#39;s a Stuzhik of a different version nearby, the connection status panel in the &quot;Friends&quot; section will tell you so.</p></div><h2 id="turning-it-on" tabindex="-1">Turning it on <a class="header-anchor" href="#turning-it-on" aria-label="Permalink to &quot;Turning it on&quot;">​</a></h2><ol><li>Open &quot;Friends&quot; in the sidebar</li><li>Click &quot;Turn on&quot;</li><li>The first time you turn it on, the launcher asks who can see you. By default, nobody: Connect is on, but you don&#39;t exist for the network until you choose &quot;Friends only&quot; or &quot;Everyone&quot; (more in the <a href="#visibility">Visibility</a> section)</li><li>Your code is <code>STUZHIK-XXXXXX</code>, 6 characters after the prefix. The &quot;Invite&quot; button copies it</li></ol><h2 id="connecting-to-a-friend" tabindex="-1">Connecting to a friend <a class="header-anchor" href="#connecting-to-a-friend" aria-label="Permalink to &quot;Connecting to a friend&quot;">​</a></h2><h3 id="auto-discovery" tabindex="-1">Auto-discovery <a class="header-anchor" href="#auto-discovery" aria-label="Permalink to &quot;Auto-discovery&quot;">​</a></h3><p>If you&#39;re on the same network, Stuzhik finds each other&#39;s devices by itself — you don&#39;t need to type anything, the device shows up in the &quot;People&quot; list. Your friend must not be &quot;Invisible&quot;, though.</p><h3 id="by-code" tabindex="-1">By code <a class="header-anchor" href="#by-code" aria-label="Permalink to &quot;By code&quot;">​</a></h3><ol><li>Ask your friend for their code</li><li>Click &quot;Add device&quot; and paste the code</li><li>Confirm with the &quot;Add device&quot; button</li></ol><p>The code looks for your friend through the same network broadcast as auto-discovery — it&#39;s there to reach exactly the right person when there are many devices in the list. That&#39;s why the code also only works on the same network (real or VPN) and only if your friend isn&#39;t &quot;Invisible&quot;.</p><p>Old-format codes (4 characters) are no longer accepted. Ask your friend for a new one — their code updates by itself once they update the launcher.</p><h3 id="by-address" tabindex="-1">By address <a class="header-anchor" href="#by-address" aria-label="Permalink to &quot;By address&quot;">​</a></h3><p>If the device isn&#39;t found by itself — for example, you&#39;re on Tailscale — click &quot;Add device&quot; and enter your friend&#39;s address: <code>100.64.0.5</code> or <code>100.64.0.5:19848</code>. You can leave out the port; the standard 19848 is used. You only need to specify it if your friend&#39;s Connect took a fallback port.</p><h2 id="friends" tabindex="-1">Friends <a class="header-anchor" href="#friends" aria-label="Permalink to &quot;Friends&quot;">​</a></h2><p>A device you&#39;ve found isn&#39;t a friend yet. To add one:</p><ol><li>Click &quot;⋯&quot; next to the person (or right-click them) → &quot;Add friend&quot;. After adding by code or address, the launcher offers this itself</li><li>Your friend accepts the request on their side — it arrives in &quot;Inbox&quot; (the bell) and in the &quot;People&quot; list</li><li>After that you&#39;re friends: the launcher recognizes your friend by a signature made with their key, and nobody can pretend to be them</li></ol><p>The launcher remembers friends together with their addresses — up to eight per friend: local network, VPN, internet. When you turn on Connect, it reaches out to them at every remembered address at once by itself — so a friend is found even where auto-discovery doesn&#39;t work, and after one of you has left the shared local network (see <a href="#tailscale-and-other-networks-without-broadcast">Tailscale</a>).</p><h3 id="check-connection" tabindex="-1">Check connection <a class="header-anchor" href="#check-connection" aria-label="Permalink to &quot;Check connection&quot;">​</a></h3><p>A person&#39;s card (click them in the list) has a &quot;Check connection&quot; button. It does a real handshake — the same one as before a modpack transfer — to every known address at once, and shows the result for each: &quot;answers, N ms&quot;, &quot;no answer&quot;, &quot;different Stuzhik version&quot; or &quot;you are hidden from them&quot;. Next to the address you see what kind of network it is: local network, Tailscale, Radmin VPN, Hamachi or internet.</p><p>For a friend, the check is available even when they&#39;re &quot;offline&quot;: if a remembered address comes back to life, your friend shows up in the list right away.</p><h2 id="visibility" tabindex="-1">Visibility <a class="header-anchor" href="#visibility" aria-label="Permalink to &quot;Visibility&quot;">​</a></h2><p>You choose the mode in Connect Settings:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Who sees you</th></tr></thead><tbody><tr><td>Invisible</td><td>Nobody. The device doesn&#39;t go on the network at all: it answers no one and announces nothing about itself. Friends won&#39;t find you — only you can find them</td></tr><tr><td>Friends only</td><td>Only friends see your nickname, modpacks and what you&#39;re playing. The device&#39;s presence on the network is noticeable to everyone — otherwise friends couldn&#39;t find you — but only a friend can tell that it&#39;s you: the identifying marker changes every 10 minutes and means nothing to outsiders</td></tr><tr><td>Everyone</td><td>Any Stuzhik user on this network sees you in the list — with your nickname, if showing it is turned on</td></tr></tbody></table><p>You can also hide from a single friend: &quot;Hide from this friend&quot; in their menu. To them you&#39;re &quot;Invisible&quot;; everyone else sees you as usual.</p><h2 id="profile" tabindex="-1">Profile <a class="header-anchor" href="#profile" aria-label="Permalink to &quot;Profile&quot;">​</a></h2><p>Your own card — &quot;My profile&quot; → &quot;Customize&quot;, the &quot;Appearance&quot; tab. Others see the card exactly as you see it yourself:</p><ul><li><strong>Banner</strong> — a live effect in the header or across the whole card, and &quot;Banner colour&quot;</li><li><strong>Avatar</strong> — the picture is cropped to a 256×256 square. &quot;Behind the picture&quot;: &quot;Default&quot;, a colour of your choice or &quot;Transparent&quot; — for PNG and WebP with a transparent background</li><li><strong>Frames</strong> — separately for the avatar and for the whole card: line, double, glow, gradient and animated ones. &quot;Frame colour&quot; — the accent or your own</li><li><strong>Accent</strong> and the &quot;About you&quot; line</li></ul><p>A colour can be picked on the square, with an eyedropper from the screen, or pasted as text: <code>#4f8cff</code>, <code>rgb(79 140 255)</code>, <code>hsl(…)</code> or just a colour name.</p><p>Who sees the appearance is decided by &quot;Who sees my profile style&quot; in Connect settings: &quot;Everyone who can see me&quot; or &quot;Friends only&quot;. Nickname and online visibility are set separately.</p><h2 id="transferring-modpacks" tabindex="-1">Transferring modpacks <a class="header-anchor" href="#transferring-modpacks" aria-label="Permalink to &quot;Transferring modpacks&quot;">​</a></h2><p>You can&#39;t send a modpack to a friend: Connect only works by &quot;pulling&quot;. Your friend takes the modpack themselves, and your launcher asks you for permission — and the question says plainly what your friend wants to get from you.</p><h3 id="opening-a-modpack-to-friends" tabindex="-1">Opening a modpack to friends <a class="header-anchor" href="#opening-a-modpack-to-friends" aria-label="Permalink to &quot;Opening a modpack to friends&quot;">​</a></h3><p>By default, modpacks aren&#39;t published — they don&#39;t exist for the network. To open one: right-click the modpack (or &quot;⋯&quot;) → &quot;Sharing&quot; → &quot;Friends only&quot; or &quot;Everyone on the network&quot;. For your friends to have something to choose from, &quot;Show modpack list&quot; must be turned on in Connect Settings.</p><p>Who can ask for a modpack, and whether you&#39;re asked every time, is also set in Connect Settings. By default only friends can ask, and every transfer happens only with your consent.</p><h3 id="getting-a-modpack-from-a-friend" tabindex="-1">Getting a modpack from a friend <a class="header-anchor" href="#getting-a-modpack-from-a-friend" aria-label="Permalink to &quot;Getting a modpack from a friend&quot;">​</a></h3><ol><li>Open your friend&#39;s card → &quot;Modpacks&quot; → &quot;Refresh&quot; to get the list</li><li>Click &quot;Get&quot; next to the modpack you want. Or use &quot;Get modpack…&quot; in your friend&#39;s menu — there you first see what will be downloaded and what you already have</li><li>Your friend gets the question &quot;Transfer request: … wants to receive from you …&quot; — the files start moving only when they click &quot;Allow&quot;</li></ol><p>The question doesn&#39;t disappear on a timer: it waits for an answer as long as the person asking is connected. One &quot;Allow&quot; covers the whole transfer — if the connection drops, resuming won&#39;t ask again. The &quot;Remember for this user&quot; checkbox remembers the answer for this friend and this modpack.</p><h3 id="during-a-transfer" tabindex="-1">During a transfer <a class="header-anchor" href="#during-a-transfer" aria-label="Permalink to &quot;During a transfer&quot;">​</a></h3><ul><li>Progress is in the transfers block of the &quot;Friends&quot; section; the full list is in &quot;All transfers&quot;</li><li>Cancel is there too, and whoever is getting the modpack can also pause and resume</li><li>Only missing and changed files are transferred</li><li>If the connection drops, the transfer continues from where it stopped, not from the beginning</li><li>Every downloaded file is checked against its hash before it goes into the modpack</li></ul><h2 id="coop-build" tabindex="-1">Co-op build <a class="header-anchor" href="#coop-build" aria-label="Permalink to &quot;Co-op build {#coop-build}&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Experimental feature</p><p>Turned on in Settings → General → &quot;Experimental features&quot;. While it&#39;s off, it isn&#39;t anywhere in the interface.</p></div><p>A build can be put together with friends: the host opens a room, friends join, propose and discuss mods, and edit configs.</p><h3 id="opening-a-room" tabindex="-1">Opening a room <a class="header-anchor" href="#opening-a-room" aria-label="Permalink to &quot;Opening a room&quot;">​</a></h3><p>&quot;Friends&quot; → &quot;Build together&quot; → one of your builds, &quot;New build&quot; (from scratch — friends add the mods themselves) or a project from the <a href="/en/guide/builder.html">Builder</a>. The same window has &quot;Who can join&quot;:</p><ul><li><strong>&quot;Friends&quot;</strong> — the default, confirmed friends only</li><li><strong>&quot;Anyone who sees me&quot;</strong> — strangers can only watch</li><li><strong>&quot;By invitation&quot;</strong> — only those ticked in the room settings</li></ul><h3 id="in-the-room" tabindex="-1">In the room <a class="header-anchor" href="#in-the-room" aria-label="Permalink to &quot;In the room&quot;">​</a></h3><ul><li><strong>Roles.</strong> An &quot;Editor&quot; changes the contents directly, a &quot;Member&quot; puts changes to a vote, a &quot;Viewer&quot; watches and discusses. A stranger is always a viewer. The host sets roles and permissions (view and edit configs, vote, take the build without asking, copy the room) in the room settings</li><li><strong>Build editor</strong> — &quot;Open the build editor&quot;: the tabs &quot;Build&quot;, &quot;Catalog&quot;, &quot;Compatibility&quot;, &quot;Configs&quot;. Only the host installs mods: a member&#39;s edit is a proposal, and the host&#39;s launcher takes the files themselves from Modrinth and CurseForge</li><li><strong>Compatibility</strong> — &quot;By composition&quot; and &quot;Dependency graph&quot; are open to everyone in the room, no need to install the build for that</li><li><strong>Proposals and discussion</strong> — votes, the &quot;Pack edits&quot; feed (a change to the contents can be undone) and &quot;Discussion&quot; — the room&#39;s shared chat</li></ul><h3 id="your-own-copy" tabindex="-1">Your own copy <a class="header-anchor" href="#your-own-copy" aria-label="Permalink to &quot;Your own copy&quot;">​</a></h3><p>&quot;Get the pack&quot; installs a copy of the host&#39;s build for you; &quot;Update my copy automatically&quot; keeps up with the host&#39;s changes. Making a room of your own based on someone else&#39;s (&quot;My own room based on this one&quot;) is possible only if the host gave the &quot;Copy the room&quot; permission — by default nobody has it.</p><p>When the host goes offline, the room closes. A pinned room (&quot;Pin the room&quot;) comes back by itself when the host reappears.</p><h2 id="if-you-are-on-different-networks" tabindex="-1">If you are on different networks <a class="header-anchor" href="#if-you-are-on-different-networks" aria-label="Permalink to &quot;If you are on different networks&quot;">​</a></h2><p>Home routers and mobile internet almost always block a direct connection between different networks — that&#39;s how NAT works; it&#39;s not a Stuzhik bug and not something we can get around on our own. What works is a shared virtual network over the internet: you both install the same VPN app, it puts your devices on one network, and Connect then works on that network.</p><p>We don&#39;t develop or support these apps — this is just a recommendation of what works. Stuzhik isn&#39;t affiliated with these services and doesn&#39;t distribute them: only the names are given here; find the official website with a search engine.</p><table tabindex="0"><thead><tr><th>Option</th><th>Difficulty</th><th>How friends are found</th></tr></thead><tbody><tr><td>Radmin VPN</td><td>Easy</td><td>By themselves, like on a regular LAN</td></tr><tr><td>ZeroTier</td><td>Medium</td><td>By themselves, when you&#39;re both in the same ZeroTier network</td></tr><tr><td>Tailscale</td><td>Hard</td><td>By address once, by themselves after that — <a href="#tailscale-and-other-networks-without-broadcast">see below</a></td></tr></tbody></table><p>Hamachi also puts devices on a shared network, and discovery works in it by itself. Tips on these options are also in the launcher itself, in the &quot;Friends&quot; section (also without links — names only).</p><h3 id="tailscale-and-other-networks-without-broadcast" tabindex="-1">Tailscale and other networks without broadcast <a class="header-anchor" href="#tailscale-and-other-networks-without-broadcast" aria-label="Permalink to &quot;Tailscale and other networks without broadcast&quot;">​</a></h3><p>Tailscale and other IP-level tunnels don&#39;t carry broadcast packets, so auto-discovery and the code find nobody in them. You need to add your friend by address — but only once:</p><ol><li>Ask your friend for their Tailscale address — it looks like <code>100.x.y.z</code></li><li>&quot;Add device&quot; → enter that address. You can leave out the port: it&#39;s 19848 by default</li><li>Add them as a friend — your friend accepts the request</li></ol><p>After that, everything happens by itself. Once you&#39;re friends, after the very first handshake in which your friend proved who they are with their signature, the launcher remembers their address. When Connect is turned on, and then every 5 minutes, it reaches out to the remembered address by itself, and once it gets through, keeps your friend online as long as they respond. A friend who got through to you on their own also shows up in the list. Co-op build rooms, profile style and &quot;playing …&quot; reach such a friend the same way as over a local network.</p><p>Only confirmed friends are remembered. In &quot;Invisible&quot; mode the launcher reaches out to nobody, and it never reaches out to a friend you&#39;re hidden from.</p><h2 id="firewall" tabindex="-1">Firewall <a class="header-anchor" href="#firewall" aria-label="Permalink to &quot;Firewall&quot;">​</a></h2><p>Connect works over UDP only: discovery on port 19847, connections on 19848. If a port is taken by another program, Connect takes a fallback one (+10, +20 or +30).</p><p>On Windows, both ports need one firewall rule — &quot;Stuzhik Connect&quot;. The &quot;Add firewall rule&quot; button in the &quot;Friends&quot; section adds it (Windows will ask for permission). The rule from versions before 0.0.19 opened transfers over TCP and no longer helps — the connection screen notices it and offers to set the rule up again: press &quot;Add firewall rule&quot; once more, and the new one replaces the old one.</p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><ul><li>Connect connections run over QUIC with TLS 1.3 and are encrypted entirely — both the files and every message, including the handshake itself. Key exchange is a hybrid of X25519 and ML-KEM-768; the keys are new for every connection</li><li>The launcher recognizes a friend by a signature made with their key, bound to this connection: an overheard signature can&#39;t be presented in another connection</li><li>An observer on the same network sees that a connection exists, its size and that it&#39;s Stuzhik — but not its contents</li><li>Files leave only after you click &quot;Allow&quot; — nothing is taken from you without asking. That&#39;s the default; in the &quot;Sharing modpacks&quot; settings, &quot;Ask for permission&quot; can be switched to &quot;Except friends&quot; or &quot;Never&quot;</li><li>Executable files (<code>.exe</code>, <code>.bat</code>, <code>.ps1</code>, <code>.sh</code>, etc.) are never transferred — not even with a <code>.disabled</code> suffix</li><li>A blocked user can&#39;t send requests and isn&#39;t visible in the list</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="my-friend-can-t-be-found-on-the-network" tabindex="-1">My friend can&#39;t be found on the network <a class="header-anchor" href="#my-friend-can-t-be-found-on-the-network" aria-label="Permalink to &quot;My friend can&#39;t be found on the network&quot;">​</a></h3><ol><li>Have you both turned on Connect, and are you both on version 0.0.19 or newer?</li><li>Is your friend not &quot;Invisible&quot;? In that mode there&#39;s no way to find them</li><li>Are you really on the same network — physical or through a shared VPN? The VPN app must be connected on both sides, not just installed</li><li>Auto-discovery doesn&#39;t work in Tailscale — add your friend by address (<a href="#tailscale-and-other-networks-without-broadcast">see above</a>)</li><li>Firewall: in the &quot;Friends&quot; section — &quot;Add firewall rule&quot;</li><li>If you&#39;re already friends — &quot;Check connection&quot; in their card will show what exactly is wrong</li></ol><h3 id="a-transfer-is-stuck" tabindex="-1">A transfer is stuck <a class="header-anchor" href="#a-transfer-is-stuck" aria-label="Permalink to &quot;A transfer is stuck&quot;">​</a></h3><ol><li>Check the transfers in the &quot;Friends&quot; section — it may be paused</li><li>Resume it manually</li><li>Still stuck — cancel it and get the modpack again: only missing and changed files are transferred</li></ol><h3 id="a-friend-request-doesn-t-arrive" tabindex="-1">A friend request doesn&#39;t arrive <a class="header-anchor" href="#a-friend-request-doesn-t-arrive" aria-label="Permalink to &quot;A friend request doesn&#39;t arrive&quot;">​</a></h3><ul><li>Your friend may have &quot;Accept friend requests&quot; turned off in Connect Settings — then requests are dropped silently, and the sender never finds out</li><li>If your friend is &quot;Invisible&quot;, they can&#39;t be seen — so there&#39;s nowhere to send the request</li><li>In &quot;Friends only&quot; mode, strangers see you without a nickname, as &quot;Anonymous&quot;. To make sure your friend finds exactly you, give them your code</li></ul><h2 id="what-s-next" tabindex="-1">What&#39;s next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next?&quot;">​</a></h2><ul><li><a href="/en/guide/modpacks.html">Modpacks</a></li><li><a href="/en/guide/collections.html">Mod Collections</a></li><li><a href="/en/faq.html">FAQ</a></li></ul>',76)])])}const y=t(r,[["render",i]]);export{f as __pageData,y as default};
